/**
 * One autogenerated sidebar per docs instance: the information architecture comes from the folder layout the
 * site generator writes, so adding, replacing or removing a page never requires a navigation change.
 *
 * A part that carries one subtree of the site - a system - needs one thing more: a way out, back to the
 * systems index. That link is <b>not</b> here. This module is shared by every docs instance of a part, so it
 * cannot know which environment a reader is browsing, and a link built without that sent someone in the dev
 * tree to the main environment's index. It is prepended by `sidebarItemsGenerator` in `docusaurus.config.js`,
 * where the environment is in scope - see `escapePointOf` there.
 *
 * An identical sidebar across the parts is deliberately not attempted - see the enabler's modularization plan.
 */
module.exports = {
    docs: [{type: 'autogenerated', dirName: '.'}],
};
